function confirmedVTBalance(person,month){let balance=0;for(const [key,r] of Object.entries(state.records)){if(!key.endsWith(':'+person)||key.slice(0,7)>month)continue;prepare(r,key.slice(0,7));balance+=r.transfers.filter(t=>!t.voided).reduce((n,t)=>n+t.amount,0)-Object.values(r.costs).reduce((n,v)=>n+v,0);}return balance;}
function summaryTotals(){const month=$('#month').value;let commissionPending=0,commissionPaid=0,discount=0,vtPending=0,vtCredit=0;const people=state.people.map(p=>{const l=ledger(p.id),cs=commissionSummary(p.id,month),paid=l.rows.reduce((n,w)=>n+w.paid,0),balance=confirmedVTBalance(p.id,month),need=Math.max(0,-balance);commissionPending+=cs.remaining;commissionPaid+=cs.paid;discount+=cs.discount;vtPending+=need;vtCredit+=Math.max(0,balance);return {person:p,commission:cs.remaining,commissionPaid:cs.paid,vtPaid:paid,vtPending:need};});const t=companyTotals(),c=companyMonth(),active=c.items.filter(e=>!e.voided),sum=list=>list.reduce((n,e)=>n+(e.amount||0)+(e.fees||0),0),paidFixed=sum(active.filter(e=>e.kind==='fixed'&&e.paidDate)),paidVariable=sum(active.filter(e=>e.kind==='variable'&&e.paidDate)),pendingFixed=sum(active.filter(e=>e.kind==='fixed'&&!e.paidDate)),pendingVariable=sum(active.filter(e=>e.kind==='variable'&&!e.paidDate)),advancePaid=(state.advances||[]).filter(a=>!a.voided&&a.date.startsWith(month)).reduce((n,a)=>n+a.amount,0),currentBalance=t.revenue-t.tax-paidFixed-paidVariable-commissionPaid-t.vtPaid-advancePaid,pendingWithoutTax=pendingFixed+pendingVariable+commissionPending+vtPending;return {...t,people,commissionPending,commissionPaid,discount,vtPending,vtCredit,paidFixed,paidVariable,pendingFixed,pendingVariable,advancePaid,currentBalance,pendingWithoutTax,afterPending:currentBalance-pendingWithoutTax,missingAmounts:active.filter(e=>e.amount===null).length};}
function renderSummary(){const t=summaryTotals(),value=n=>money(n/100),row=(label,n)=>`<div><dt>${label}</dt><dd>${value(n)}</dd></div>`;$('#stats').innerHTML=[['Faturamento do mês',t.revenue,'Calculado automaticamente pelas vendas'],['Saldo atual calculado',t.currentBalance,'Após pagamentos registrados e reserva do imposto'],['Ainda a pagar',t.pendingWithoutTax,'Somente despesas e obrigações confirmadas'],['Após quitar as pendências',t.afterPending,'Sem desconto de VT previsto']].map(([label,n,note])=>`<div class="stat"><span class="stat-label">${label}</span><strong>${value(n)}</strong><small>${note}</small></div>`).join('');$('#summary-section').innerHTML=`<div class="section-head"><div><span class="eyebrow">VISÃO GERAL DO MÊS</span><h2>Resumo financeiro</h2><p>Pagamentos já feitos e contas em aberto, separados.</p></div><button data-main-view="company">Ver gastos e imposto</button></div>${t.missingAmounts?`<div class="summary-notice">${t.missingAmounts} gasto(s) ainda sem valor. O resultado ficará incompleto até preenchê-los.</div>`:''}<div class="summary-columns"><section class="summary-panel"><h3>Quanto sobra atualmente</h3><dl class="ledger">${row('Faturamento automático das vendas',t.revenue)}${row('− Reserva do imposto ('+t.taxRate.toLocaleString('pt-BR')+'%)',t.tax)}${row('− Gastos fixos já pagos',t.paidFixed)}${row('− Gastos variados já pagos',t.paidVariable)}${row('− Comissões líquidas já pagas',t.commissionPaid)}${row('− VT já pago',t.vtPaid)}${row('− Vales e adiantamentos pagos no mês',t.advancePaid)}</dl><div class="profit-result"><span>Saldo atual calculado</span><strong>${value(t.currentBalance)}</strong></div><p class="hint">O faturamento bruto é calculado pelas vendas cadastradas no mês, antes do desconto do imposto. Não é o saldo bancário: recebimentos e pagamentos de outros períodos podem ser diferentes.</p><p class="hint">Contas e comissões já pagas ficam somente neste bloco. Os valores seguem o mês de referência dos lançamentos; os vales seguem a data em que foram pagos.</p></section><section class="summary-panel"><h3>O que ainda falta pagar</h3><dl class="ledger">${row('Gastos fixos pendentes',t.pendingFixed)}${row('Gastos variados pendentes',t.pendingVariable)}${row('Comissões líquidas pendentes',t.commissionPending)}${row('VT confirmado ainda sem cobertura',t.vtPending)}${row('Total pendente',t.pendingWithoutTax)}</dl><div class="profit-result"><span>Saldo após quitar essas pendências</span><strong>${value(t.afterPending)}</strong></div><p class="hint">Saldo atual menos o total pendente. Gastos marcados como pagos saem desta lista e entram no bloco ao lado, sem duplicar o desconto.</p><p class="hint">VT previsto para dias sem confirmação não é descontado. O VT pendente considera somente presenças confirmadas, descontando pagamentos e créditos anteriores de cada pessoa.</p><p class="hint">O imposto já foi reservado no bloco atual e não é descontado novamente. O sistema ainda não registra sua quitação.</p><p class="hint">Vales já pagos reduzem a comissão líquida a pagar; a comissão bruta não é subtraída novamente.</p></section></div><div class="section-head"><div><h3>Pagamentos por pessoa</h3><p class="hint">Valores pagos e pendências confirmadas do período.</p></div><button data-main-view="team">Abrir equipe</button></div><div class="sale-table-wrap"><table class="sale-table"><thead><tr><th>Pessoa</th><th>VT pago</th><th>VT confirmado a pagar</th><th>Comissão já paga</th><th>Comissão a pagar</th></tr></thead><tbody>${t.people.map(p=>`<tr><td>${esc(p.person.name)}</td><td>${value(p.vtPaid)}</td><td>${value(p.vtPending)}</td><td>${value(p.commissionPaid)}</td><td>${value(p.commission)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Saldo calculado com os lançamentos cadastrados. Créditos de VT são individuais; o saldo de uma pessoa não cobre outra.</p>`;}
